package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.util.Objects;

import static org.junit.jupiter.api.Assertions.*;

public class OptionHashCodeTest {

    private static void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field f = Option.class.getDeclaredField(fieldName);
        f.setAccessible(true);
        f.set(target, value);
    }

    @Test
    public void testHashCode_equalForSameOptAndLongOpt() {
        Option o1 = new Option("a", "description");
        o1.setLongOpt("long");
        Option o2 = new Option("a", "description");
        o2.setLongOpt("long");

        int h1 = o1.hashCode();
        int h2 = o2.hashCode();

        assertEquals(h1, h2, "hashCodes should be equal for same longOption and option");
        assertEquals(Objects.hash("long", "a"), h1, "hashCode should match Objects.hash(longOption, option)");
    }

    @Test
    public void testHashCode_notEqualForDifferentLongOpt() {
        Option o1 = new Option("b", "desc");
        o1.setLongOpt("longOne");
        Option o2 = new Option("b", "desc");
        o2.setLongOpt("longTwo");

        int h1 = o1.hashCode();
        int h2 = o2.hashCode();

        assertNotEquals(h1, h2, "hashCodes should differ when longOption differs");
    }

    @Test
    public void testHashCode_handlesNullLongOptionAndOptionUsingReflection() throws Exception {
        // create two Options with different initial opts, then null out both 'option' and 'longOption' via reflection
        Option o1 = new Option("x", "desc");
        Option o2 = new Option("y", "desc");

        setPrivateField(o1, "option", null);
        setPrivateField(o1, "longOption", null);

        setPrivateField(o2, "option", null);
        setPrivateField(o2, "longOption", null);

        int h1 = o1.hashCode();
        int h2 = o2.hashCode();

        assertEquals(h1, h2, "hashCodes should be equal when both longOption and option are null");
        assertEquals(Objects.hash(null, null), h1, "hashCode should match Objects.hash(null, null)");
    }

    @Test
    public void testHashCode_equalWhenOnlyLongOptionNull() {
        // Create two Options with same option string and do not set longOption (remains null)
        Option o1 = new Option("z", "desc");
        Option o2 = new Option("z", "another");

        // longOption is null by default; ensure option field (opt) is same
        int h1 = o1.hashCode();
        int h2 = o2.hashCode();

        assertEquals(h1, h2, "hashCodes should be equal when longOption is null and option strings are equal");
        assertEquals(Objects.hash(null, "z"), h1, "hashCode should match Objects.hash(null, option)");
    }
}

